import{_ as o,o as a,c as e,ag as r}from"./chunks/framework.CAXxHpAX.js";const c=JSON.parse('{"title":"如何看待财富与布施","description":"","frontmatter":{},"headers":[],"relativePath":"20-专题研究/topic-财富与布施.md","filePath":"20-专题研究/topic-财富与布施.md","lastUpdated":1778040484000}'),l={name:"20-专题研究/topic-财富与布施.md"};function d(h,t,i,u,n,q){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="如何看待财富与布施" tabindex="-1">如何看待财富与布施 <a class="header-anchor" href="#如何看待财富与布施" aria-label="Permalink to &quot;如何看待财富与布施&quot;">​</a></h1><blockquote><p>专题分析：金钱与慈善中的修行智慧 组合模型：自然务实 + 对法不执 + 圆融中和</p></blockquote><hr><h2 id="一、了空居士对财富的根本看法" tabindex="-1">一、了空居士对财富的根本看法 <a class="header-anchor" href="#一、了空居士对财富的根本看法" aria-label="Permalink to &quot;一、了空居士对财富的根本看法&quot;">​</a></h2><p>了空居士对财富的态度非常辩证：<strong>财富本身不是问题，执着于财富才是问题</strong>。</p><blockquote><p><strong>&quot;心胸不用宽广，也不用狭隘，最关键，就是以智慧去看待一切。该花一万我不会花九千，不该花的五元，我可能五元钱都不愿意花，我会看得很准的。&quot;</strong></p></blockquote><p>— 答疑专辑2019_处世篇</p><ul><li><strong>自然务实</strong>：赚钱是正常的事，修行人也需要吃饭穿衣</li><li><strong>对法不执</strong>：有钱不执着于钱，没钱也不执着于穷</li><li><strong>圆融中和</strong>：不走极端——既不拼命赚钱也不视金钱如粪土。<strong>取之有道，用之不执</strong></li></ul><hr><h2 id="二、布施的真正含义" tabindex="-1">二、布施的真正含义 <a class="header-anchor" href="#二、布施的真正含义" aria-label="Permalink to &quot;二、布施的真正含义&quot;">​</a></h2><h3 id="布施不是交易" tabindex="-1">布施不是交易 <a class="header-anchor" href="#布施不是交易" aria-label="Permalink to &quot;布施不是交易&quot;">​</a></h3><blockquote><p><strong>&quot;庄严佛土者，即非庄严，是名庄严。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经10分-应无所住生心">金刚经10分-应无所住生心</a></p><p>做好事是自然的流露，不是求功德。布施后心里没有&quot;我在布施&quot;的念头——&quot;雷锋帮完人就走了，不等着对方说谢谢。&quot;</p><h3 id="布施的分寸" tabindex="-1">布施的分寸 <a class="header-anchor" href="#布施的分寸" aria-label="Permalink to &quot;布施的分寸&quot;">​</a></h3><blockquote><p><strong>&quot;了解就多帮助，不了解就少帮助，这是最客观的。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经4分-布施的分寸">金刚经4分-布施的分寸</a></p><p>不是所有的请求都必须答应。量力而行，真诚评估自己能不能帮、该不该帮。平等心不是&quot;一个价&quot;。</p><h3 id="随喜也是布施" tabindex="-1">随喜也是布施 <a class="header-anchor" href="#随喜也是布施" aria-label="Permalink to &quot;随喜也是布施&quot;">​</a></h3><blockquote><p><strong>&quot;随喜是众善奉行的第一步。看到别人做好事，心生欢喜，这就是随喜。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经11分-随喜即众善">金刚经11分-随喜即众善</a></p><p>你看到别人在做好事，发自内心地高兴，这也是一种布施。福报不一定是你捐了多少，而是你的心量有多大。</p><hr><h2 id="三、常见财富误区" tabindex="-1">三、常见财富误区 <a class="header-anchor" href="#三、常见财富误区" aria-label="Permalink to &quot;三、常见财富误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>正解</th><th>原文依据</th></tr></thead><tbody><tr><td>修行人不能有钱</td><td>修行人也要吃饭，重点是不执着</td><td>答疑专辑2019处世篇</td></tr><tr><td>布施越多福报越大</td><td>关键是心态，不是数字</td><td>&quot;庄严佛土者，即非庄严&quot; — <a href="/60-原文段落/金刚经10分-应无所住生心">金刚经10分-应无所住生心</a></td></tr><tr><td>贫穷的人更有修行</td><td>穷不等于有修行，富不等于没修行</td><td>—</td></tr><tr><td>捐了钱就要有回报</td><td>交易心态，不是真布施</td><td>—</td></tr></tbody></table><hr><h2 id="四、了空居士原话" tabindex="-1">四、了空居士原话 <a class="header-anchor" href="#四、了空居士原话" aria-label="Permalink to &quot;四、了空居士原话&quot;">​</a></h2><blockquote><p><strong>&quot;以无我无人无众生无寿者修一切善法，即得阿耨多罗三藐三菩提。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经23分-净心行善">金刚经23分-净心行善</a></p><blockquote><p><strong>&quot;庄严佛土者，即非庄严，是名庄严。做好事是自然的流露，不是求功德。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经10分-应无所住生心">金刚经10分-应无所住生心</a></p><blockquote><p><strong>&quot;随喜是众善奉行的第一步。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经11分-随喜即众善">金刚经11分-随喜即众善</a></p><blockquote><p><strong>&quot;了解就多帮助，不了解就少帮助，这是最客观的。&quot;</strong></p></blockquote><p>— <a href="/60-原文段落/金刚经4分-布施的分寸">金刚经4分-布施的分寸</a></p><hr><h2 id="五、推荐模型" tabindex="-1">五、推荐模型 <a class="header-anchor" href="#五、推荐模型" aria-label="Permalink to &quot;五、推荐模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-自然务实">自然务实</a> — 务实对待财富，取之有道</li><li><a href="/10-核心模型/model-对法不执">对法不执</a> — 不执着于财富，不执功德相</li><li><a href="/10-核心模型/model-圆融中和">圆融中和</a> — 不走极端，不贪不吝</li></ul><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-义">dict-义</a> — 义利统一，对整体有利的就是义</li><li><a href="/50-概念资料/dict-正">dict-正</a> — 以整体观定财富获取方式的正与不正</li></ul><hr><blockquote><p>创建日期：2026-05-06 | 修订：2026-05-07（删除无法验证出处的引文，全部原话添加原文段落链接） 来源：金刚经第4分、第10分、第11分、第23分，答疑专辑2019处世篇</p></blockquote>',42)])])}const p=o(l,[["render",d]]);export{c as __pageData,p as default};
